import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './App.css';


function App() {
  const [posts, setPosts] = useState([]);
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [editId, setEditId] = useState(null);

  const fetchPosts = async () => {
    const res = await axios.get('http://localhost:5000/posts');
    setPosts(res.data);
  };

  const handleSubmit = async () => {
    if (!title || !content) return;

    if (editId) {
      await axios.put(`http://localhost:5000/posts/${editId}`, { title, content });
      setEditId(null);
    } else {
      await axios.post('http://localhost:5000/posts', { title, content });
    }
    setTitle('');
    setContent('');
    fetchPosts();
  };

  const handleEdit = (post) => {
    setEditId(post._id);
    setTitle(post.title);
    setContent(post.content);
  };

  const handleDelete = async (id) => {
    await axios.delete(`http://localhost:5000/posts/${id}`);
    fetchPosts();
  };

  useEffect(() => {
    fetchPosts();
  }, []);

  return (
    <div style={{ padding: 20, maxWidth: 600, margin: 'auto' }}>
      <h1>My Blog</h1>
      <input value={title} onChange={e => setTitle(e.target.value)} placeholder="Title" /><br />
      <textarea value={content} onChange={e => setContent(e.target.value)} placeholder="Content" /><br />
      <button onClick={handleSubmit}>{editId ? "Update Post" : "Create Post"}</button>
      {posts.map(post => (
        <div key={post._id} style={{ border: '1px solid gray', padding: 10, marginTop: 10 }}>
          <h3>{post.title}</h3>
          <p>{post.content}</p>
          <button onClick={() => handleEdit(post)}>Edit</button>
          <button onClick={() => handleDelete(post._id)}>Delete</button>
        </div>
      ))}
    </div>
  );
}

export default App;
